== V1__sheet.sql
-- A sheet: the unit everything else in the app is kept under. Created the first time its id is loaded.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
== V2__sheet_today.sql
-- The sheet's "today": the date every date-dependent decision and default date on the sheet uses,
-- never the real clock. A sheet starts with the real date when it is created.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE) WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
== V3__person.sql
-- People on a sheet, listed in the order they were added (by id). Grade is one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet(id),
    name     VARCHAR(200) NOT NULL,
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person(sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on the sheet, compared without regard to case and ignoring surrounding
-- spaces. Names are stored trimmed; name_key is the comparison form the unique index holds.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(TRIM(name)));
CREATE UNIQUE INDEX person_sheet_name ON person(sheet_id, name_key);
== V5__claim.sql
-- A person's claims: an amount (0.00 or more, two decimals), a date and a note (may be empty).
-- Listed newest first (by id).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet(id),
    person_id  BIGINT         NOT NULL REFERENCES person(id),
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim(sheet_id, id);
== V6__rate.sql
-- The sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet(id),
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0),
    PRIMARY KEY (sheet_id, grade)
);
== V7__claim_status.sql
-- A claim's status: DRAFT -> OPEN -> SETTLED, or DRAFT/OPEN -> VOID. SETTLED and VOID are final.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL;
== V8__claim_number.sql
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ... no gaps, never reused).
-- A draft has none; voiding clears it. The sheet keeps the last number it gave.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
== V9__claim_settled_due.sql
-- A settled claim's due, fixed when it was settled: its amount times its person's grade rate at that
-- moment, divided by 100, rounded half up to two decimals. NULL while a claim is not settled (its due
-- is live), and NULL for a settled claim whose grade had no rate then (its due stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);
UPDATE claim c SET settled_due = (
    SELECT ROUND(c.amount * r.pct / 100, 2) FROM person p JOIN rate r ON r.sheet_id = p.sheet_id AND r.grade = p.grade
    WHERE p.id = c.person_id)
WHERE c.status = 'SETTLED';
== V10__rate_from.sql
-- A rate may carry a from-date: a grade may have several rates, one per from-date (and at most one
-- with none, which applies from the beginning of time). A claim uses the rate whose from-date is the
-- latest on or before its date.
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
CREATE INDEX rate_sheet_grade ON rate (sheet_id, grade);
== V11__claim_opened_by.sql
-- Who opened a claim (the signed-in user's name). NULL while a draft. They may not settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(100);
== V12__person_version.sql
-- The version of a person: 0 when added, one more on each stored edit. An edit names the version
-- it was made from and is refused when the person has been saved since.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
== V13__statement.sql
-- A person's statements: how many have been taken, and the last one's due-total (NULL when it was n/a,
-- or none was taken) and date (the sheet's today when it was taken; NULL when none was taken).
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total DECIMAL(14, 2);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- Whether a claim is bound by its person's last statement (it counted then), and the figure it was bound
-- to (NULL when its figure was n/a then: its due stays live). The person's next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);
== V14__period.sql
-- The sheet's periods: a name unique on the sheet (compared without regard to case, ignoring surrounding
-- spaces) and an inclusive from and to date. No two periods on a sheet overlap. A claim belongs to the
-- period whose dates contain its date, or to none.
CREATE TABLE period (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    name      VARCHAR(200) NOT NULL,
    name_key  VARCHAR(200) GENERATED ALWAYS AS (LOWER(TRIM(name))),
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period(sheet_id, name_key);
== V15__period_closed.sql
-- Whether a period is closed, and its due-total fixed when it was closed (NULL while open). No claim dated in a
-- closed period can be added, edited or change status.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(14, 2);
== V16__person_retired.sql
-- The date a person is retired from (null: not retired). A claim dated after it is refused; the person's
-- claims keep counting in every total.
ALTER TABLE person ADD COLUMN retired_from DATE;
== V17__person_held.sql
-- Whether a person is on hold. While held, their OPEN claims count in no live total (their own, the sheet's,
-- a period's); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
== V18__role_clerk_limit.sql
-- The sheet's roles: a user name (as signed in, trimmed) and its role, clerk or steward. A name with no row
-- is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    PRIMARY KEY (sheet_id, user_name)
);
-- The sheet's clerk limit (two decimals; NULL: no limit). A clerk may settle a claim only when its due is at or
-- below it (a due of n/a is within any limit); a steward settles anything.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(14, 2);
== V19__sheet_floor.sql
-- The sheet's floor (two decimals): a claim's live due is at least it. A settled claim's fixed due, a figure a
-- statement bound and a closed period's fixed total keep the figure they took.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(14, 2) NOT NULL DEFAULT 1.00;
== V20__sheet_terms.sql
-- The sheet's terms (a number of days): a claim's due-by is its date plus the terms in force.
ALTER TABLE sheet ADD COLUMN terms_days INT NOT NULL DEFAULT 14;
== V21__sheet_late_pct.sql
-- The sheet's late percent (two decimals): an overdue claim's due gains it, of its figure, for every full 30 days
-- it is overdue. A settled claim's fixed due keeps the charge it had then.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(7, 2) NOT NULL DEFAULT 0.00;
== V22__person_patron.sql
-- A person's patrons: other people on the same sheet, each named at most once. A person is never their own patron.
CREATE TABLE person_patron (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    person_id BIGINT       NOT NULL REFERENCES person(id),
    patron_id BIGINT       NOT NULL REFERENCES person(id),
    PRIMARY KEY (person_id, patron_id),
    CHECK (person_id <> patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron(sheet_id);
== V23__person_grade.sql
-- A person's grade is dated: each grade they are given applies from its from-date (null: from the beginning of
-- time, the first grade a person was given), at most one per from-date. A claim uses the grade whose from-date is
-- the latest on or before its date; the list shows the one in force on the sheet's today.
CREATE TABLE person_grade (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    person_id BIGINT       NOT NULL REFERENCES person(id),
    grade     CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    from_date DATE
);
CREATE INDEX person_grade_sheet ON person_grade(sheet_id, person_id);
INSERT INTO person_grade (sheet_id, person_id, grade, from_date) SELECT sheet_id, id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
== V24__claim_corrects.sql
-- A claim may be a correction: a negative amount that names, by number, a SETTLED claim of the same person it
-- corrects (null: not a correction). The amount may now be below 0.00 for a correction; the column is rebuilt to
-- drop its 0.00-or-more check.
ALTER TABLE claim ADD COLUMN corrects INT;
ALTER TABLE claim ADD COLUMN amount_signed DECIMAL(14, 2);
UPDATE claim SET amount_signed = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN amount_signed RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
== V25__sheet_policy_date.sql
-- The sheet's rounding policy date (null: the sheet's today): a claim dated before it rounds half up, one dated on or
-- after it half to even. A correction rounds by the date of the claim it corrects.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
== V26__period_numbering.sql
-- The sheet's period numbering from (null: off). While it is a date and the sheet's today is on or after it, a
-- claim opened is numbered within its period: <period name>-<n>, counting from 1 in each period; a claim in no
-- period is numbered X-<n> in its own sequence. A claim's number (and the number a correction names) is now text:
-- a sheet-wide number is kept as its digits.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(220);
-- The last number given in each period's sequence on a sheet ('X' for the claims in no period), by the
-- period's name as compared on the sheet (lower case, trimmed).
CREATE TABLE period_number (
    sheet_id    VARCHAR(100) NOT NULL REFERENCES sheet(id),
    seq_key     VARCHAR(220) NOT NULL,
    last_number INT          NOT NULL,
    PRIMARY KEY (sheet_id, seq_key)
);
== V27__grade_terms_claim_due_by.sql
-- A grade's own terms (a number of days) on a sheet; a grade without a row uses the sheet's terms.
CREATE TABLE grade_terms (
    sheet_id   VARCHAR(100) NOT NULL REFERENCES sheet(id),
    grade      CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    terms_days INT          NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's due-by is fixed when it is created: its date plus the terms of its person's grade in force on its date
-- (else the sheet's terms). It does not change when the terms or the claim's date change later.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY, (SELECT s.terms_days FROM sheet s WHERE s.id = c.sheet_id), c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V28__claim_log.sql
-- A claim's status log: one entry per status it has had (its DRAFT one written when it was added), oldest first
-- (by id): who gave it the status, the sheet's today then (NULL when the sheet had none) and the claim's due as its
-- row showed it then (NULL when n/a).
CREATE TABLE claim_log (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)   NOT NULL REFERENCES sheet(id),
    claim_id BIGINT         NOT NULL REFERENCES claim(id),
    status   VARCHAR(20)    NOT NULL,
    by_user  VARCHAR(100)   NOT NULL,
    on_date  DATE,
    due      DECIMAL(14, 2)
);
CREATE INDEX claim_log_sheet ON claim_log(sheet_id, claim_id, id);
== V29__person_hold.sql
-- A person's holds are dated: each runs from its from-date (null: from the beginning of time) to its to-date
-- (null: open-ended), both included, and a person may have several over time. Only their OPEN claims dated within a
-- hold, and not bound by a statement, are left out of the live totals. A person held before keeps an open-ended
-- hold from the beginning of time.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    person_id BIGINT       NOT NULL REFERENCES person(id),
    from_date DATE,
    to_date   DATE
);
CREATE INDEX person_hold_sheet ON person_hold(sheet_id, person_id);
INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) SELECT sheet_id, id, NULL, NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V30__rate_to.sql
-- A rate may carry a to-date: it applies through it. A claim dated after the to-date of the rate that
-- would apply to it (the latest from-date on or before its date) has no rate.
ALTER TABLE rate ADD COLUMN to_date DATE;
== V31__sheet_cap.sql
-- The sheet's cap (two decimals; NULL: none). A person's due-total is at most it; the rest is their excess.
ALTER TABLE sheet ADD COLUMN due_cap DECIMAL(14, 2);
== V32__period_person_total.sql
-- Each person's due-total in a closed period, fixed when it was closed: one row per person on the sheet at that
-- moment (a person added later has none, and shows 0.00). The period's closed_total is these added up. Dropped
-- when the period is reopened.
CREATE TABLE period_person_total (
    sheet_id    VARCHAR(100)   NOT NULL REFERENCES sheet(id),
    period_name VARCHAR(200)   NOT NULL,
    person_id   BIGINT         NOT NULL REFERENCES person(id),
    total       DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (sheet_id, period_name, person_id)
);
== V33__dated_settings.sql
-- The sheet's settings that carry a figure are dated: each key (floor, late-pct, terms, terms-A/B/C, clerk-limit,
-- cap) holds at most one value per from-date. The value in force on a date is the one with the latest from-date on
-- or before it; before every from-date the sheet's starting value applies (floor 1.00, late-pct 0.00, terms 14,
-- a grade's terms: the sheet's terms, clerk-limit and cap: none). A NULL value is blank: none (clerk-limit, cap) or
-- the sheet's terms (a grade's terms). The policy date and the period numbering from stay undated, on the sheet.
CREATE TABLE setting_value (
    sheet_id    VARCHAR(100) NOT NULL REFERENCES sheet(id),
    setting_key VARCHAR(20)  NOT NULL,
    from_date   DATE         NOT NULL,
    val         VARCHAR(20),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- Values already kept carry over in force from the beginning of time.
INSERT INTO setting_value (sheet_id, setting_key, from_date, val)
    SELECT id, 'floor', DATE '0001-01-01', CAST(due_floor AS VARCHAR(20)) FROM sheet WHERE due_floor <> 1.00;
INSERT INTO setting_value (sheet_id, setting_key, from_date, val)
    SELECT id, 'late-pct', DATE '0001-01-01', CAST(late_pct AS VARCHAR(20)) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO setting_value (sheet_id, setting_key, from_date, val)
    SELECT id, 'terms', DATE '0001-01-01', CAST(terms_days AS VARCHAR(20)) FROM sheet WHERE terms_days <> 14;
INSERT INTO setting_value (sheet_id, setting_key, from_date, val)
    SELECT id, 'clerk-limit', DATE '0001-01-01', CAST(clerk_limit AS VARCHAR(20)) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO setting_value (sheet_id, setting_key, from_date, val)
    SELECT id, 'cap', DATE '0001-01-01', CAST(due_cap AS VARCHAR(20)) FROM sheet WHERE due_cap IS NOT NULL;
INSERT INTO setting_value (sheet_id, setting_key, from_date, val)
    SELECT sheet_id, 'terms-' || grade, DATE '0001-01-01', CAST(terms_days AS VARCHAR(20)) FROM grade_terms;
DROP TABLE grade_terms;
ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN late_pct;
ALTER TABLE sheet DROP COLUMN terms_days;
ALTER TABLE sheet DROP COLUMN clerk_limit;
ALTER TABLE sheet DROP COLUMN due_cap;
== V34__claim_deferred_until.sql
-- An OPEN claim may be deferred to a date after the sheet's today (null: never deferred). Until the sheet's today
-- reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a statement.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V35__claim_proofs.sql
-- A claim's proofs count, raised by one at a time (never on a SETTLED or VOID claim). A claim whose due is above the
-- sheet's proof threshold in force on its date cannot be settled or approved while it has none. The proof threshold
-- is a dated setting (setting_value key proof-threshold; blank: none).
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
== V36__sheet_permission.sql
-- The sheet's permission matrix: for an action (open, settle, void, reassign, close, reopen) the roles that may take
-- it, a comma separated list of clerk and steward. Not dated. An action with no row (or a blank one) keeps the
-- standing rule: open, settle, void and close by clerk and steward; reassign and reopen by steward.
CREATE TABLE sheet_permission (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet(id),
    action   VARCHAR(20)  NOT NULL,
    roles    VARCHAR(100) NOT NULL,
    PRIMARY KEY (sheet_id, action)
);
== V37__role_viewer.sql
-- A third role, viewer: sees everything on the sheet and may change nothing. The role check is widened by
-- rebuilding the table (its CHECK constraint was unnamed).
CREATE TABLE sheet_role_new (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer')),
    PRIMARY KEY (sheet_id, user_name)
);
INSERT INTO sheet_role_new (sheet_id, user_name, role) SELECT sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
== V38__sheet_grace_days.sql
-- The sheet's grace days (null: off; not dated). When the sheet's today is changed, each open period whose to-date
-- plus them is before the new today is closed.
ALTER TABLE sheet ADD COLUMN grace_days INT;
== V39__claim_split_from.sql
-- The number of the claim an OPEN claim was split from (null: not split off one). Splitting an OPEN claim leaves
-- the original with the rest of its amount (and no split-from of its own) and adds a new OPEN claim with the
-- split-off amount, the same date and note and the next number.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(220);
== V40__person_watch.sql
-- The users watching a person, each at most once, in the order they started watching (by id). Stopping removes the
-- row, so watching again goes to the end.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    person_id BIGINT       NOT NULL REFERENCES person(id),
    user_name VARCHAR(100) NOT NULL,
    UNIQUE (person_id, user_name)
);
CREATE INDEX person_watch_sheet ON person_watch(sheet_id, person_id, id);
== V41__sheet_delegation.sql
-- A steward's delegation of the steward role to a user for a from-date to a to-date, both included, by the sheet's
-- today. While the sheet's today is inside the range the user acts as a steward in every rule, and every audit line
-- of a change they make (not ROLLUP or TOTALS) ends with for=<the steward who delegated>.
CREATE TABLE sheet_delegation (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet(id),
    user_name    VARCHAR(100) NOT NULL,
    from_date    DATE         NOT NULL,
    to_date      DATE         NOT NULL,
    delegated_by VARCHAR(100) NOT NULL
);
CREATE INDEX sheet_delegation_user ON sheet_delegation(sheet_id, user_name);
== V42__sheet_archived.sql
-- Whether a steward has archived the sheet. An archived sheet stays visible, and every change to it is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
== V43__person_terms.sql
-- A person may have terms of their own, in days (null: none). A new claim's due-by is its date plus the person's own
-- terms, else their grade's, else the sheet's.
ALTER TABLE person ADD COLUMN terms INTEGER;
== V44__claim_lock.sql
-- Who holds the claim's editor open (null: no one). Taken at the edit button, released when the editor is saved or
-- cancelled, and released on every claim of the sheet when the sheet's today changes.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(255);
== V45__claim_late_entry.sql
-- Whether the claim was added while its period was soft-closed (a late entry). Fixed when it is added.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN NOT NULL DEFAULT FALSE;
-- A soft-closed period: its due-total and each person's are fixed (as a close does), but its claims can still be
-- changed. Closed and soft are never both set.
ALTER TABLE period ADD COLUMN soft BOOLEAN NOT NULL DEFAULT FALSE;
== V46__person_statement.sql
-- Each statement taken of a person, in the order taken: its due-total (NULL when it was n/a) and date. The person
-- keeps the last one's on their row; cancelling the last one removes it, and the row shows the one before it. A
-- person stated before keeps their last statement here (the earlier ones were not kept).
CREATE TABLE person_statement (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(100) NOT NULL REFERENCES sheet(id),
    person_id      BIGINT       NOT NULL REFERENCES person(id),
    due_total      DECIMAL(14, 2),
    statement_date DATE
);
CREATE INDEX person_statement_sheet ON person_statement(sheet_id, person_id);
INSERT INTO person_statement (sheet_id, person_id, due_total, statement_date)
    SELECT sheet_id, id, stated_total, statement_date FROM person WHERE statement_count > 0;

tool_use_result.stdout:
== V1__sheet.sql
-- A sheet: the unit everything else in the app is kept under. Created the first time its id is loaded.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
== V2__sheet_today.sql
-- The sheet's "today": the date every date-dependent decision and default date on the sheet uses,
-- never the real clock. A sheet starts with the real date when it is created.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE) WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
== V3__person.sql
-- People on a sheet, listed in the order they were added (by id). Grade is one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet(id),
    name     VARCHAR(200) NOT NULL,
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person(sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on the sheet, compared without regard to case and ignoring surrounding
-- spaces. Names are stored trimmed; name_key is the comparison form the unique index holds.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(TRIM(name)));
CREATE UNIQUE INDEX person_sheet_name ON person(sheet_id, name_key);
== V5__claim.sql
-- A person's claims: an amount (0.00 or more, two decimals), a date and a note (may be empty).
-- Listed newest first (by id).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet(id),
    person_id  BIGINT         NOT NULL REFERENCES person(id),
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim(sheet_id, id);
== V6__rate.sql
-- The sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet(id),
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0),
    PRIMARY KEY (sheet_id, grade)
);
== V7__claim_status.sql
-- A claim's status: DRAFT -> OPEN -> SETTLED, or DRAFT/OPEN -> VOID. SETTLED and VOID are final.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL;
== V8__claim_number.sql
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ... no gaps, never reused).
-- A draft has none; voiding clears it. The sheet keeps the last number it gave.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
== V9__claim_settled_due.sql
-- A settled claim's due, fixed when it was settled: its amount times its person's grade rate at that
-- moment, divided by 100, rounded half up to two decimals. NULL while a claim is not settled (its due
-- is live), and NULL for a settled claim whose grade had no rate then (its due stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);
UPDATE claim c SET settled_due = (
    SELECT ROUND(c.amount * r.pct / 100, 2) FROM person p JOIN rate r ON r.sheet_id = p.sheet_id AND r.grade = p.grade
    WHERE p.id = c.person_id)
WHERE c.status = 'SETTLED';
== V10__rate_from.sql
-- A rate may carry a from-date: a grade may have several rates, one per from-date (and at most one
-- with none, which applies from the beginning of time). A claim uses the rate whose from-date is the
-- latest on or before its date.
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
CREATE INDEX rate_sheet_grade ON rate (sheet_id, grade);
== V11__claim_opened_by.sql
-- Who opened a claim (the signed-in user's name). NULL while a draft. They may not settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(100);
== V12__person_version.sql
-- The version of a person: 0 when added, one more on each stored edit. An edit names the version
-- it was made from and is refused when the person has been saved since.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
== V13__statement.sql
-- A person's statements: how many have been taken, and the last one's due-total (NULL when it was n/a,
-- or none was taken) and date (the sheet's today when it was taken; NULL when none was taken).
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total DECIMAL(14, 2);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- Whether a claim is bound by its person's last statement (it counted then), and the figure it was bound
-- to (NULL when its figure was n/a then: its due stays live). The person's next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);
== V14__period.sql
-- The sheet's periods: a name unique on the sheet (compared without regard to case, ignoring surrounding
-- spaces) and an inclusive from and to date. No two periods on a sheet overlap. A claim belongs to the
-- period whose dates contain its date, or to none.
CREATE TABLE period (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    name      VARCHAR(200) NOT NULL,
    name_key  VARCHAR(200) GENERATED ALWAYS AS (LOWER(TRIM(name))),
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period(sheet_id, name_key);
== V15__period_closed.sql
-- Whether a period is closed, and its due-total fixed when it was closed (NULL while open). No claim dated in a
-- closed period can be added, edited or change status.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(14, 2);
== V16__person_retired.sql
-- The date a person is retired from (null: not retired). A claim dated after it is refused; the person's
-- claims keep counting in every total.
ALTER TABLE person ADD COLUMN retired_from DATE;
== V17__person_held.sql
-- Whether a person is on hold. While held, their OPEN claims count in no live total (their own, the sheet's,
-- a period's); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
== V18__role_clerk_limit.sql
-- The sheet's roles: a user name (as signed in, trimmed) and its role, clerk or steward. A name with no row
-- is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    PRIMARY KEY (sheet_id, user_name)
);
-- The sheet's clerk limit (two decimals; NULL: no limit). A clerk may settle a claim only when its due is at or
-- below it (a due of n/a is within any limit); a steward settles anything.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(14, 2);
== V19__sheet_floor.sql
-- The sheet's floor (two decimals): a claim's live due is at least it. A settled claim's fixed due, a figure a
-- statement bound and a closed period's fixed total keep the figure they took.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(14, 2) NOT NULL DEFAULT 1.00;
== V20__sheet_terms.sql
-- The sheet's terms (a number of days): a claim's due-by is its date plus the terms in force.
ALTER TABLE sheet ADD COLUMN terms_days INT NOT NULL DEFAULT 14;
== V21__sheet_late_pct.sql
-- The sheet's late percent (two decimals): an overdue claim's due gains it, of its figure, for every full 30 days
-- it is overdue. A settled claim's fixed due keeps the charge it had then.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(7, 2) NOT NULL DEFAULT 0.00;
== V22__person_patron.sql
-- A person's patrons: other people on the same sheet, each named at most once. A person is never their own patron.
CREATE TABLE person_patron (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    person_id BIGINT       NOT NULL REFERENCES person(id),
    patron_id BIGINT       NOT NULL REFERENCES person(id),
    PRIMARY KEY (person_id, patron_id),
    CHECK (person_id <> patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron(sheet_id);
== V23__person_grade.sql
-- A person's grade is dated: each grade they are given applies from its from-date (null: from the beginning of
-- time, the first grade a person was given), at most one per from-date. A claim uses the grade whose from-date is
-- the latest on or before its date; the list shows the one in force on the sheet's today.
CREATE TABLE person_grade (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    person_id BIGINT       NOT NULL REFERENCES person(id),
    grade     CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    from_date DATE
);
CREATE INDEX person_grade_sheet ON person_grade(sheet_id, person_id);
INSERT INTO person_grade (sheet_id, person_id, grade, from_date) SELECT sheet_id, id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
== V24__claim_corrects.sql
-- A claim may be a correction: a negative amount that names, by number, a SETTLED claim of the same person it
-- corrects (null: not a correction). The amount may now be below 0.00 for a correction; the column is rebuilt to
-- drop its 0.00-or-more check.
ALTER TABLE claim ADD COLUMN corrects INT;
ALTER TABLE claim ADD COLUMN amount_signed DECIMAL(14, 2);
UPDATE claim SET amount_signed = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN amount_signed RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
== V25__sheet_policy_date.sql
-- The sheet's rounding policy date (null: the sheet's today): a claim dated before it rounds half up, one dated on or
-- after it half to even. A correction rounds by the date of the claim it corrects.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
== V26__period_numbering.sql
-- The sheet's period numbering from (null: off). While it is a date and the sheet's today is on or after it, a
-- claim opened is numbered within its period: <period name>-<n>, counting from 1 in each period; a claim in no
-- period is numbered X-<n> in its own sequence. A claim's number (and the number a correction names) is now text:
-- a sheet-wide number is kept as its digits.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(220);
-- The last number given in each period's sequence on a sheet ('X' for the claims in no period), by the
-- period's name as compared on the sheet (lower case, trimmed).
CREATE TABLE period_number (
    sheet_id    VARCHAR(100) NOT NULL REFERENCES sheet(id),
    seq_key     VARCHAR(220) NOT NULL,
    last_number INT          NOT NULL,
    PRIMARY KEY (sheet_id, seq_key)
);
== V27__grade_terms_claim_due_by.sql
-- A grade's own terms (a number of days) on a sheet; a grade without a row uses the sheet's terms.
CREATE TABLE grade_terms (
    sheet_id   VARCHAR(100) NOT NULL REFERENCES sheet(id),
    grade      CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    terms_days INT          NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's due-by is fixed when it is created: its date plus the terms of its person's grade in force on its date
-- (else the sheet's terms). It does not change when the terms or the claim's date change later.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY, (SELECT s.terms_days FROM sheet s WHERE s.id = c.sheet_id), c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V28__claim_log.sql
-- A claim's status log: one entry per status it has had (its DRAFT one written when it was added), oldest first
-- (by id): who gave it the status, the sheet's today then (NULL when the sheet had none) and the claim's due as its
-- row showed it then (NULL when n/a).
CREATE TABLE claim_log (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)   NOT NULL REFERENCES sheet(id),
    claim_id BIGINT         NOT NULL REFERENCES claim(id),
    status   VARCHAR(20)    NOT NULL,
    by_user  VARCHAR(100)   NOT NULL,
    on_date  DATE,
    due      DECIMAL(14, 2)
);
CREATE INDEX claim_log_sheet ON claim_log(sheet_id, claim_id, id);
== V29__person_hold.sql
-- A person's holds are dated: each runs from its from-date (null: from the beginning of time) to its to-date
-- (null: open-ended), both included, and a person may have several over time. Only their OPEN claims dated within a
-- hold, and not bound by a statement, are left out of the live totals. A person held before keeps an open-ended
-- hold from the beginning of time.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    person_id BIGINT       NOT NULL REFERENCES person(id),
    from_date DATE,
    to_date   DATE
);
CREATE INDEX person_hold_sheet ON person_hold(sheet_id, person_id);
INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) SELECT sheet_id, id, NULL, NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V30__rate_to.sql
-- A rate may carry a to-date: it applies through it. A claim dated after the to-date of the rate that
-- would apply to it (the latest from-date on or before its date) has no rate.
ALTER TABLE rate ADD COLUMN to_date DATE;
== V31__sheet_cap.sql
-- The sheet's cap (two decimals; NULL: none). A person's due-total is at most it; the rest is their excess.
ALTER TABLE sheet ADD COLUMN due_cap DECIMAL(14, 2);
== V32__period_person_total.sql
-- Each person's due-total in a closed period, fixed when it was closed: one row per person on the sheet at that
-- moment (a person added later has none, and shows 0.00). The period's closed_total is these added up. Dropped
-- when the period is reopened.
CREATE TABLE period_person_total (
    sheet_id    VARCHAR(100)   NOT NULL REFERENCES sheet(id),
    period_name VARCHAR(200)   NOT NULL,
    person_id   BIGINT         NOT NULL REFERENCES person(id),
    total       DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (sheet_id, period_name, person_id)
);
== V33__dated_settings.sql
-- The sheet's settings that carry a figure are dated: each key (floor, late-pct, terms, terms-A/B/C, clerk-limit,
-- cap) holds at most one value per from-date. The value in force on a date is the one with the latest from-date on
-- or before it; before every from-date the sheet's starting value applies (floor 1.00, late-pct 0.00, terms 14,
-- a grade's terms: the sheet's terms, clerk-limit and cap: none). A NULL value is blank: none (clerk-limit, cap) or
-- the sheet's terms (a grade's terms). The policy date and the period numbering from stay undated, on the sheet.
CREATE TABLE setting_value (
    sheet_id    VARCHAR(100) NOT NULL REFERENCES sheet(id),
    setting_key VARCHAR(20)  NOT NULL,
    from_date   DATE         NOT NULL,
    val         VARCHAR(20),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- Values already kept carry over in force from the beginning of time.
INSERT INTO setting_value (sheet_id, setting_key, from_date, val)
    SELECT id, 'floor', DATE '0001-01-01', CAST(due_floor AS VARCHAR(20)) FROM sheet WHERE due_floor <> 1.00;
INSERT INTO setting_value (sheet_id, setting_key, from_date, val)
    SELECT id, 'late-pct', DATE '0001-01-01', CAST(late_pct AS VARCHAR(20)) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO setting_value (sheet_id, setting_key, from_date, val)
    SELECT id, 'terms', DATE '0001-01-01', CAST(terms_days AS VARCHAR(20)) FROM sheet WHERE terms_days <> 14;
INSERT INTO setting_value (sheet_id, setting_key, from_date, val)
    SELECT id, 'clerk-limit', DATE '0001-01-01', CAST(clerk_limit AS VARCHAR(20)) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO setting_value (sheet_id, setting_key, from_date, val)
    SELECT id, 'cap', DATE '0001-01-01', CAST(due_cap AS VARCHAR(20)) FROM sheet WHERE due_cap IS NOT NULL;
INSERT INTO setting_value (sheet_id, setting_key, from_date, val)
    SELECT sheet_id, 'terms-' || grade, DATE '0001-01-01', CAST(terms_days AS VARCHAR(20)) FROM grade_terms;
DROP TABLE grade_terms;
ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN late_pct;
ALTER TABLE sheet DROP COLUMN terms_days;
ALTER TABLE sheet DROP COLUMN clerk_limit;
ALTER TABLE sheet DROP COLUMN due_cap;
== V34__claim_deferred_until.sql
-- An OPEN claim may be deferred to a date after the sheet's today (null: never deferred). Until the sheet's today
-- reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a statement.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V35__claim_proofs.sql
-- A claim's proofs count, raised by one at a time (never on a SETTLED or VOID claim). A claim whose due is above the
-- sheet's proof threshold in force on its date cannot be settled or approved while it has none. The proof threshold
-- is a dated setting (setting_value key proof-threshold; blank: none).
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
== V36__sheet_permission.sql
-- The sheet's permission matrix: for an action (open, settle, void, reassign, close, reopen) the roles that may take
-- it, a comma separated list of clerk and steward. Not dated. An action with no row (or a blank one) keeps the
-- standing rule: open, settle, void and close by clerk and steward; reassign and reopen by steward.
CREATE TABLE sheet_permission (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet(id),
    action   VARCHAR(20)  NOT NULL,
    roles    VARCHAR(100) NOT NULL,
    PRIMARY KEY (sheet_id, action)
);
== V37__role_viewer.sql
-- A third role, viewer: sees everything on the sheet and may change nothing. The role check is widened by
-- rebuilding the table (its CHECK constraint was unnamed).
CREATE TABLE sheet_role_new (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer')),
    PRIMARY KEY (sheet_id, user_name)
);
INSERT INTO sheet_role_new (sheet_id, user_name, role) SELECT sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
== V38__sheet_grace_days.sql
-- The sheet's grace days (null: off; not dated). When the sheet's today is changed, each open period whose to-date
-- plus them is before the new today is closed.
ALTER TABLE sheet ADD COLUMN grace_days INT;
== V39__claim_split_from.sql
-- The number of the claim an OPEN claim was split from (null: not split off one). Splitting an OPEN claim leaves
-- the original with the rest of its amount (and no split-from of its own) and adds a new OPEN claim with the
-- split-off amount, the same date and note and the next number.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(220);
== V40__person_watch.sql
-- The users watching a person, each at most once, in the order they started watching (by id). Stopping removes the
-- row, so watching again goes to the end.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    person_id BIGINT       NOT NULL REFERENCES person(id),
    user_name VARCHAR(100) NOT NULL,
    UNIQUE (person_id, user_name)
);
CREATE INDEX person_watch_sheet ON person_watch(sheet_id, person_id, id);
== V41__sheet_delegation.sql
-- A steward's delegation of the steward role to a user for a from-date to a to-date, both included, by the sheet's
-- today. While the sheet's today is inside the range the user acts as a steward in every rule, and every audit line
-- of a change they make (not ROLLUP or TOTALS) ends with for=<the steward who delegated>.
CREATE TABLE sheet_delegation (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet(id),
    user_name    VARCHAR(100) NOT NULL,
    from_date    DATE         NOT NULL,
    to_date      DATE         NOT NULL,
    delegated_by VARCHAR(100) NOT NULL
);
CREATE INDEX sheet_delegation_user ON sheet_delegation(sheet_id, user_name);
== V42__sheet_archived.sql
-- Whether a steward has archived the sheet. An archived sheet stays visible, and every change to it is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
== V43__person_terms.sql
-- A person may have terms of their own, in days (null: none). A new claim's due-by is its date plus the person's own
-- terms, else their grade's, else the sheet's.
ALTER TABLE person ADD COLUMN terms INTEGER;
== V44__claim_lock.sql
-- Who holds the claim's editor open (null: no one). Taken at the edit button, released when the editor is saved or
-- cancelled, and released on every claim of the sheet when the sheet's today changes.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(255);
== V45__claim_late_entry.sql
-- Whether the claim was added while its period was soft-closed (a late entry). Fixed when it is added.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN NOT NULL DEFAULT FALSE;
-- A soft-closed period: its due-total and each person's are fixed (as a close does), but its claims can still be
-- changed. Closed and soft are never both set.
ALTER TABLE period ADD COLUMN soft BOOLEAN NOT NULL DEFAULT FALSE;
== V46__person_statement.sql
-- Each statement taken of a person, in the order taken: its due-total (NULL when it was n/a) and date. The person
-- keeps the last one's on their row; cancelling the last one removes it, and the row shows the one before it. A
-- person stated before keeps their last statement here (the earlier ones were not kept).
CREATE TABLE person_statement (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(100) NOT NULL REFERENCES sheet(id),
    person_id      BIGINT       NOT NULL REFERENCES person(id),
    due_total      DECIMAL(14, 2),
    statement_date DATE
);
CREATE INDEX person_statement_sheet ON person_statement(sheet_id, person_id);
INSERT INTO person_statement (sheet_id, person_id, due_total, statement_date)
    SELECT sheet_id, id, stated_total, statement_date FROM person WHERE statement_count > 0;

