package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** Rates by sheet: per grade, at most one per from-date (and at most one with no from-date). */
@Repository
public class RateRepository {

    private static final RowMapper<Rate> ROW = (rs, i) -> new Rate(rs.getString("sheet_id"),
            rs.getString("grade"), rs.getBigDecimal("pct"), rs.getObject("from_date", LocalDate.class),
            rs.getObject("to_date", LocalDate.class));

    private final JdbcTemplate jdbc;

    public RateRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's rates by grade, each grade's earliest first (the one with no from-date before all). */
    public List<Rate> list(String sheetId) {
        return jdbc.query("SELECT * FROM rate WHERE sheet_id = ? ORDER BY grade, from_date NULLS FIRST", ROW, sheetId);
    }

    /** The grade's rate in force on the date: the one whose from-date is the latest on or before it (no
     *  from-date counting as the beginning of time); empty when none applies, or that one's to-date is before the date. */
    public Optional<Rate> on(String sheetId, String grade, LocalDate date) {
        return list(sheetId).stream().filter(r -> r.grade().equals(grade) && r.appliesOn(date))
                .max(Comparator.comparing(Rate::from, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> !r.endedBy(date));
    }

    /** Set the grade's rate from the from-date (null: from the beginning of time) through the to-date (null:
     *  with no end), replacing any it had from that same date. */
    public Rate set(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to) {
        Date fromDate = from != null ? Date.valueOf(from) : null;
        Date toDate = to != null ? Date.valueOf(to) : null;
        jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                sheetId, grade, fromDate);
        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date) VALUES (?, ?, ?, ?, ?)",
                sheetId, grade, pct, fromDate, toDate);
        return new Rate(sheetId, grade, pct, from, to);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet's rate for a grade: a percent with two decimals, in force from its from-date (null: from the
 *  beginning of time) through its to-date (null: with no end). */
public record Rate(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to) {

    /** Whether this rate could apply on the date: it has no from-date, or its from-date is on or before it. */
    public boolean appliesOn(LocalDate date) {
        return from == null || !from.isAfter(date);
    }

    /** Whether the date is after this rate's to-date: the rate has ended by then. */
    public boolean endedBy(LocalDate date) {
        return to != null && to.isBefore(date);
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveRate {
    public void save(@PathVariable("sheetId") String sheetId, @Val RateInput input,
            RateRepository repository, Out<Rate> rate) {
        rate.set(repository.set(sheetId.trim(), input.grade(), input.pct(), input.from(), input.to()));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;

/** A person's dated grades, earliest first: each applies from its from-date (null: from the beginning of time). */
public record Grades(List<Grade> history) {

    /** A grade given from a from-date (null: from the beginning of time). */
    public record Grade(String grade, LocalDate from) {
        boolean appliesOn(LocalDate date) {
            return from == null || !from.isAfter(date);
        }
    }

    public static final Grades NONE = new Grades(List.of());

    /** The grade in force on the date: the one whose from-date is the latest on or before it; "" when none applies. */
    public String on(LocalDate date) {
        return history.stream().filter(g -> g.appliesOn(date))
                .max(Comparator.comparing(Grade::from, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(Grade::grade).orElse("");
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;

/** A person's holds, in the order they were put on: each runs from its from-date (null: from the beginning of time)
 *  to its to-date (null: open-ended), both included. */
public record Holds(List<Hold> history) {

    /** A hold from a from-date to a to-date (either null: unbounded on that side). */
    public record Hold(LocalDate from, LocalDate to) {
        boolean covers(LocalDate date) {
