package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** People by sheet, in the order they were added. */
@Repository
public class PersonRepository {

    private static final RowMapper<Person> ROW = (rs, i) -> new Person(rs.getLong("id"),
            rs.getString("sheet_id"), rs.getString("name"), null, rs.getLong("version"),
            rs.getInt("statement_count"), rs.getBigDecimal("stated_total"), rs.getObject("statement_date", LocalDate.class),
            rs.getObject("retired_from", LocalDate.class), Grades.NONE, Holds.NONE, (Integer) rs.getObject("terms"));

    private record GradeRow(long personId, Grades.Grade grade) {
    }

    private static final RowMapper<GradeRow> GRADE_ROW = (rs, i) -> new GradeRow(rs.getLong("person_id"),
            new Grades.Grade(rs.getString("grade"), rs.getObject("from_date", LocalDate.class)));

    private record HoldRow(long personId, Holds.Hold hold) {
    }

    private static final RowMapper<HoldRow> HOLD_ROW = (rs, i) -> new HoldRow(rs.getLong("person_id"),
            new Holds.Hold(rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));

    private final JdbcTemplate jdbc;

    public PersonRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Person> list(String sheetId) {
        return graded(sheetId, jdbc.query("SELECT * FROM person WHERE sheet_id = ? ORDER BY id", ROW, sheetId));
    }

    /** The person on this sheet, or null when absent. */
    public Person find(String sheetId, long id) {
        return graded(sheetId, jdbc.query("SELECT * FROM person WHERE sheet_id = ? AND id = ?", ROW, sheetId, id))
                .stream().findFirst().orElse(null);
    }

    /** The person on this sheet with this name (compared as nameInUse compares), or null when absent. */
    public Person findByName(String sheetId, String name) {
        return graded(sheetId, jdbc.query("SELECT * FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?))", ROW,
                sheetId, name)).stream().findFirst().orElse(null);
    }

    /** The people with their dated grades, the grade in force on the sheet's today, and their holds. */
    private List<Person> graded(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return people;
        }
        LocalDate today = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
        Map<Long, List<Grades.Grade>> byPerson = jdbc.query(
                "SELECT * FROM person_grade WHERE sheet_id = ? ORDER BY person_id, from_date NULLS FIRST", GRADE_ROW,
                sheetId).stream().collect(Collectors.groupingBy(GradeRow::personId,
                        Collectors.mapping(GradeRow::grade, Collectors.toList())));
        Map<Long, List<Holds.Hold>> holdsByPerson = jdbc.query(
                "SELECT * FROM person_hold WHERE sheet_id = ? ORDER BY person_id, id", HOLD_ROW, sheetId).stream()
                .collect(Collectors.groupingBy(HoldRow::personId,
                        Collectors.mapping(HoldRow::hold, Collectors.toList())));
        return people.stream().map(p -> {
            Grades grades = new Grades(byPerson.getOrDefault(p.id(), List.of()));
            return new Person(p.id(), p.sheetId(), p.name(), grades.on(today), p.version(), p.statementCount(),
                    p.statedTotal(), p.statementDate(), p.retiredFrom(), grades,
                    new Holds(holdsByPerson.getOrDefault(p.id(), List.of())), p.terms());
        }).toList();
    }

    /** Whether another person on this sheet (other than exceptId, when given) has this name,
     *  compared without regard to case and ignoring surrounding spaces. */
    public boolean nameInUse(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND id <> ?",
                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    /** Add a person with their first grade, which applies from the beginning of time, and no terms of their own. */
    public Person insert(String sheetId, String name, String grade) {
        return insert(sheetId, name, grade, null);
    }

    /** Add a person with their first grade, which applies from the beginning of time, and their own terms (null: none). */
    public Person insert(String sheetId, String name, String grade, Integer terms) {
        var keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO person (sheet_id, name, terms) VALUES (?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setObject(3, terms, java.sql.Types.INTEGER);
            return ps;
        }, keys);
        long id = keys.getKey().longValue();
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date) VALUES (?, ?, ?, NULL)",
                sheetId, id, grade);
        return new Person(id, sheetId, name, grade, 0, 0, null, null, null,
                new Grades(List.of(new Grades.Grade(grade, null))), Holds.NONE, terms);
    }

    /** Lock the person's row until the transaction ends, so concurrent statements of them go one after the other. */
    public void lock(Person person) {
        jdbc.query("SELECT id FROM person WHERE sheet_id = ? AND id = ? FOR UPDATE", rs -> null,
                person.sheetId(), person.id());
    }

    /** Record a statement taken of the person: one more taken, with its due-total (null: n/a) and date. Leaves the version alone: a statement is not an edit of the person. */
    public void stated(Person person, BigDecimal total, LocalDate date) {
        jdbc.update("UPDATE person SET statement_count = statement_count + 1, stated_total = ?, statement_date = ? "
                + "WHERE sheet_id = ? AND id = ?", total, date, person.sheetId(), person.id());
        jdbc.update("INSERT INTO person_statement (sheet_id, person_id, due_total, statement_date) VALUES (?, ?, ?, ?)",
                person.sheetId(), person.id(), total, date);
    }

    /** Cancel the last statement taken of the person: one fewer taken, and their row shows the one before it (its
     *  due-total and date; none when there is no earlier one kept). Leaves the version alone. */
    public void unstated(Person person) {
        List<Long> kept = jdbc.queryForList("SELECT id FROM person_statement WHERE sheet_id = ? AND person_id = ? "
                + "ORDER BY id DESC", Long.class, person.sheetId(), person.id());
        if (!kept.isEmpty()) {
            jdbc.update("DELETE FROM person_statement WHERE id = ?", kept.get(0));
        }
        jdbc.update("UPDATE person SET statement_count = statement_count - 1, stated_total = NULL, statement_date = NULL "
                + "WHERE sheet_id = ? AND id = ? AND statement_count > 0", person.sheetId(), person.id());
        if (kept.size() > 1) {
            jdbc.update("UPDATE person SET stated_total = (SELECT due_total FROM person_statement WHERE id = ?), "
                    + "statement_date = (SELECT statement_date FROM person_statement WHERE id = ?) "
                    + "WHERE sheet_id = ? AND id = ?", kept.get(1), kept.get(1), person.sheetId(), person.id());
        }
    }

    /** Retire the person from the date. Leaves the version alone: retiring is not an edit of the person. */
    public void retire(Person person, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?", from, person.sheetId(), person.id());
    }

    /** Add a hold to the person from the from-date to the to-date (null: open-ended), keeping the holds they have.
     *  Leaves the version alone: holding is not an edit of the person. */
    public void hold(Person person, LocalDate from, LocalDate to) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
                person.sheetId(), person.id(), from, to);
    }

    /** Set the person's own terms in days (null: none). */
    public void terms(Person person, Integer terms) {
        jdbc.update("UPDATE person SET terms = ? WHERE sheet_id = ? AND id = ?", terms, person.sheetId(), person.id());
    }

    /** Store the person's name at its new version, only while the stored person is still at version
     *  `from`; false (nothing written) when it has been saved since. */
    public boolean update(Person person, long from) {
        return jdbc.update("UPDATE person SET name = ?, version = ? WHERE sheet_id = ? AND id = ? AND version = ?",
                person.name(), person.version(), person.sheetId(), person.id(), from) == 1;
    }

    /** Give the person the grade from the from-date (null: from the beginning of time), replacing any they were
     *  given from that same date and keeping the rest. */
    public void grade(Person person, String grade, LocalDate from) {
        Date fromDate = from != null ? Date.valueOf(from) : null;
        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date IS NOT DISTINCT FROM ?",
                person.sheetId(), person.id(), fromDate);
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date) VALUES (?, ?, ?, ?)",
                person.sheetId(), person.id(), grade, fromDate);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A person's claim: an amount (two decimals; below 0.00 only for a correction), a date, a note (may be empty), its
 *  status, its number (sheet-wide digits, or <period name>-<n> / X-<n> when numbered within its period; null while a draft; a voided claim keeps the one it had) and, once settled, the due fixed
 *  at settling (null before then, or when the person's grade had no rate then: its due stays live), and
 *  who opened it (null while a draft), whether its person's last statement bound it (it counted then) and the
 *  figure it bound it to (null when not bound, or its figure was n/a then: its due stays live), and for a correction
 *  (a negative amount) the number of the SETTLED claim of the same person it corrects (null otherwise), and its
 *  due-by, fixed when it was created: its date plus the terms of its person's grade in force on its date (else the
 *  sheet's terms); it does not change when the terms or its date change later; and the date it is deferred until (null: never
 *  deferred): an OPEN claim deferred past the sheet's today is deferred (see deferredOn); and its proofs count (0 or more,
 *  raised one at a time); and the number of the claim it was split from (null when it was not split off one); and whether it is a
 *  late entry: added while its period was soft-closed (fixed when it was added). */
public record Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
        BigDecimal statedDue, String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs,
        String splitFrom, boolean lateEntry) {

    /** Whether the claim is deferred on the sheet's today: it is OPEN and deferred until a date after today (null:
     *  no today, nothing is deferred). Deferred, it counts in no total, is not overdue, cannot be settled and is
     *  left unbound by a statement; from that date on it is an OPEN claim like any other. */
    public boolean deferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && deferredUntil.isAfter(today);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** Claims by sheet, newest first. */
@Repository
public class ClaimRepository {

    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getString("sheet_id"),
            rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getObject("claim_date", LocalDate.class),
            rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
            rs.getString("claim_number"), rs.getBigDecimal("settled_due"),
            rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"),
            rs.getString("corrects"), rs.getObject("due_by", LocalDate.class),
            rs.getObject("deferred_until", LocalDate.class), rs.getInt("proofs"), rs.getString("split_from"),
            rs.getBoolean("late_entry"));

    private final JdbcTemplate jdbc;

    public ClaimRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Claim> list(String sheetId) {
        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? ORDER BY id DESC", ROW, sheetId);
    }

    /** The claim on this sheet, or null when absent. */
    public Claim find(String sheetId, long id) {
        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id)
                .stream().findFirst().orElse(null);
    }

    public Claim insert(Claim claim) {
        var keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by, split_from, late_entry) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, claim.sheetId());
            ps.setLong(2, claim.personId());
            ps.setBigDecimal(3, claim.amount());
            ps.setObject(4, claim.date());
            ps.setString(5, claim.note());
            ps.setString(6, claim.corrects());
            ps.setObject(7, claim.dueBy());
            ps.setString(8, claim.splitFrom());
            ps.setBoolean(9, claim.lateEntry());
            return ps;
        }, keys);
        return new Claim(keys.getKey().longValue(), claim.sheetId(), claim.personId(), claim.amount(),
                claim.date(), claim.note(), ClaimStatus.DRAFT, null, null, null, false, null, claim.corrects(),
                claim.dueBy(), null, 0, claim.splitFrom(), claim.lateEntry());
    }

    /** The person's claims, newest first. */
    public List<Claim> listForPerson(String sheetId, long personId) {
        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC", ROW, sheetId,
                personId);
    }

    /** Whether the person has a SETTLED claim with this number on the sheet. */
    public boolean settledNumbered(String sheetId, long personId, String number) {
        return jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ? AND claim_number = ? AND status = ?",
                Integer.class, sheetId, personId, number, ClaimStatus.SETTLED.name()) > 0;
    }

    /** Bind the claim to a statement's figure (null: n/a, its due stays live), or unbind it (stated false). */
    public void state(Claim claim, boolean stated, BigDecimal statedDue) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet_id = ? AND id = ?",
                stated, statedDue, claim.sheetId(), claim.id());
    }

    /** Move the claim to another person, unbinding it from any statement: false when it no longer has the person
     *  and status it was loaded with (another user changed it first), and nothing is written. */
    public boolean reassign(Claim claim, long personId) {
        return jdbc.update(
                "UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL WHERE sheet_id = ? AND id = ? AND person_id = ? AND status = ?",
                personId, claim.sheetId(), claim.id(), claim.personId(), claim.status().name()) == 1;
    }

    /** Defer the claim until the date: false when it is no longer OPEN (another user changed it first), and nothing
     *  is written. */
    public boolean defer(Claim claim, LocalDate until) {
        return jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet_id = ? AND id = ? AND status = ?",
                until, claim.sheetId(), claim.id(), ClaimStatus.OPEN.name()) == 1;
    }

    /** Leave the OPEN claim with the rest of its amount after a split, unbinding it from any statement: false when
     *  it is no longer OPEN with the amount it was loaded with (another user changed it first), and nothing is
     *  written. */
    public boolean splitRest(Claim claim, BigDecimal rest) {
        return jdbc.update(
                "UPDATE claim SET amount = ?, stated = FALSE, stated_due = NULL WHERE sheet_id = ? AND id = ? AND status = ? AND amount = ?",
                rest, claim.sheetId(), claim.id(), ClaimStatus.OPEN.name(), claim.amount()) == 1;
    }

    /** Raise the claim's proofs count by one: false when it no longer has the status it was loaded with (another user
     *  changed it first), and nothing is written. */
    public boolean addProof(Claim claim) {
        return jdbc.update("UPDATE claim SET proofs = proofs + 1 WHERE sheet_id = ? AND id = ? AND status = ?",
                claim.sheetId(), claim.id(), claim.status().name()) == 1;
    }

    /** Store an edit of the claim, releasing its editor lock. */
    public void update(Claim claim) {
        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, corrects = ?, locked_by = NULL WHERE sheet_id = ? AND id = ?",
                claim.amount(), claim.date(), claim.note(), claim.corrects(), claim.sheetId(), claim.id());
    }

    /** Move the claim from one status to another, with its settled due and who opened it: false when it no longer has
     *  the status it was loaded with (another user changed it first), and nothing is written. */
    public boolean changeStatus(Claim claim, ClaimStatus to, String number, BigDecimal settledDue,
            String openedBy) {
        return jdbc.update(
                "UPDATE claim SET status = ?, claim_number = ?, settled_due = ?, opened_by = ? WHERE sheet_id = ? AND id = ? AND status = ?",
                to.name(), number, settledDue, openedBy, claim.sheetId(), claim.id(), claim.status().name()) == 1;
    }

    /** Re-date the claim with its number (a new one when its period changed): false when it no longer has the
     *  date and status it was loaded with (another user changed it first), and nothing is written. */
    public boolean redate(Claim claim, LocalDate date, String number) {
        return jdbc.update(
                "UPDATE claim SET claim_date = ?, claim_number = ? WHERE sheet_id = ? AND id = ? AND claim_date = ? AND status = ?",
                date, number, claim.sheetId(), claim.id(), claim.date(), claim.status().name()) == 1;
    }

    /** Whether the sheet numbers claims within their period now: its period numbering from is a date and its today
     *  is on or after it. */
    public boolean numberingByPeriod(String sheetId) {
        return Boolean.TRUE.equals(jdbc.query(
                "SELECT period_numbering_from IS NOT NULL AND today >= period_numbering_from FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getBoolean(1) : false, sheetId));
    }

    /** Take the next number for a claim dated on the date, as it is opened. While the sheet's period numbering from
     *  is a date and the sheet's today is on or after it, that is the next in the claim's period (<period name>-<n>),
     *  or for a claim in no period the next in its own sequence (X-<n>); otherwise it is the sheet's next number.
     *  Taking a number locks the sheet's row until the transaction ends, so concurrent openings are numbered one
     *  after the other; a rolled-back one gives its number back, so there are no gaps. */
    public String nextNumber(String sheetId, LocalDate date) {
        jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", rs -> null, sheetId);
        Boolean byPeriod = jdbc.query(
                "SELECT period_numbering_from IS NOT NULL AND today >= period_numbering_from FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getBoolean(1) : false, sheetId);
        if (!Boolean.TRUE.equals(byPeriod)) {
            jdbc.update("UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?", sheetId);
            return String.valueOf(jdbc.queryForObject("SELECT last_claim_number FROM sheet WHERE id = ?",
                    Integer.class, sheetId));
        }
        String[] period = jdbc.query(
                "SELECT name, name_key FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ? ORDER BY from_date",
                rs -> rs.next() ? new String[] { rs.getString(1), rs.getString(2) } : null, sheetId, date, date);
        String prefix = period != null ? period[0] : "X";
        String key = period != null ? "p:" + period[1] : "x";
        if (jdbc.update("UPDATE period_number SET last_number = last_number + 1 WHERE sheet_id = ? AND seq_key = ?",
                sheetId, key) == 0) {
            jdbc.update("INSERT INTO period_number (sheet_id, seq_key, last_number) VALUES (?, ?, 1)", sheetId, key);
        }
        int n = jdbc.queryForObject("SELECT last_number FROM period_number WHERE sheet_id = ? AND seq_key = ?",
                Integer.class, sheetId, key);
        return prefix + "-" + n;
    }

    /** Lock the claim's editor for the user: false when another user holds it, and nothing is written. */
    public boolean lock(Claim claim, String user) {
        return jdbc.update("UPDATE claim SET locked_by = ? WHERE sheet_id = ? AND id = ? AND (locked_by IS NULL OR locked_by = ?)",
                user, claim.sheetId(), claim.id(), user) == 1;
    }

    /** Release the user's lock on the claim's editor; another user's lock is left as it is. */
    public void unlock(Claim claim, String user) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND id = ? AND locked_by = ?",
                claim.sheetId(), claim.id(), user);
    }

    /** Who holds the claim's editor locked, or null when no one does. */
    public String lockedBy(Claim claim) {
        return jdbc.query("SELECT locked_by FROM claim WHERE sheet_id = ? AND id = ?",
                rs -> rs.next() ? rs.getString(1) : null, claim.sheetId(), claim.id());
    }

    /** Release every editor lock on the sheet's claims. */
    public void unlockAll(String sheetId) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND locked_by IS NOT NULL", sheetId);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.Dues;
import net.officefloor.hq.app.statement.LateCharge;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Each claim's status log: one line per status it has had, oldest first, as
 *  <STATUS> by <user> on <date> due=<due>, the date being the sheet's today when the status was given and the due
 *  the claim's due as its row showed it then (n/a when it had no figure). */
@Repository
public class ClaimLogRepository {

    private final JdbcTemplate jdbc;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateRepository rates;
    private final SettingRepository settings;
    private final SheetRepository sheets;

    public ClaimLogRepository(JdbcTemplate jdbc, ClaimRepository claims, PersonRepository people,
            RateRepository rates, SettingRepository settings, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Log the claim's status as stored now, given by the user, with its due as its row shows it now. */
    public void record(Claim claim, String user) {
        String sheetId = claim.sheetId();
        Claim now = claims.find(sheetId, claim.id());
        var person = people.find(sheetId, now.personId());
        BigDecimal due = Dues.shown(now, person.grades(), rates, settings.floor(sheetId),
                LateCharge.of(sheetId, settings, sheets, claims));
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due) VALUES (?, ?, ?, ?, ?, ?)",
                sheetId, now.id(), now.status().name(), user, sheets.today(sheetId), due);
    }

    /** The day (the sheet's today) the claim was last given the status, as its log records it; null when it never
     *  was, or was given it while the sheet had no today. */
    public LocalDate lastOn(String sheetId, long claimId, ClaimStatus status) {
        return jdbc.query("SELECT on_date FROM claim_log WHERE sheet_id = ? AND claim_id = ? AND status = ? ORDER BY id DESC LIMIT 1",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId, claimId, status.name());
    }

    /** The log lines of every claim on the sheet, by claim id, oldest first. */
    public Map<Long, List<String>> lines(String sheetId) {
        Map<Long, List<String>> lines = new HashMap<>();
        jdbc.query("SELECT * FROM claim_log WHERE sheet_id = ? ORDER BY id", rs -> {
            LocalDate on = rs.getObject("on_date", LocalDate.class);
            BigDecimal due = rs.getBigDecimal("due");
            lines.computeIfAbsent(rs.getLong("claim_id"), k -> new ArrayList<>())
                    .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
                            + (on != null ? on.toString() : "") + " due=" + (due != null ? due.toPlainString() : "n/a"));
        }, sheetId);
        return lines;
    }

    /** Each logged claim's status at the end of the day given, by claim id, as its log records it: the last status
     *  given on or before that day (one given while the sheet had no today counts as given by then); null when every
     *  status it has was given after it (it was added later). A claim with no log is not in the map. */
    public Map<Long, ClaimStatus> statusesAt(String sheetId, LocalDate end) {
        Map<Long, ClaimStatus> statuses = new HashMap<>();
        jdbc.query("SELECT * FROM claim_log WHERE sheet_id = ? ORDER BY id", rs -> {
            LocalDate on = rs.getObject("on_date", LocalDate.class);
            long claimId = rs.getLong("claim_id");
            if (on == null || !on.isAfter(end)) {
                statuses.put(claimId, ClaimStatus.valueOf(rs.getString("status")));
            } else {
                statuses.putIfAbsent(claimId, null);
            }
        }, sheetId);
        return statuses;
    }
}

